/*
 * prog49_bst.c – Reimplementation of the BST traversal program.
 *
 * The original binary builds a binary‑search‑tree from the command‑line
 * integer arguments and prints one of three traversals depending on the
 * first argument (mode):
 *   "in"   – inorder
 *   "pre"  – preorder
 *   "post" – postorder
 *
 * If no numbers are supplied the tree is empty and the program prints
 * "EMPTY".  An unknown mode results in "INVALID_MODE".  After a successful
 * traversal a newline is printed.
 *
 * The implementation mirrors the observable behaviour of the original
 * program while using clear, idiomatic C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct Node {
    long value;
    struct Node *left;
    struct Node *right;
} Node;

/* Insert a value into the BST. Duplicates are ignored – this matches the
   original program which never inserted a node when the value already
   existed. */
static void insert(Node **root, long v)
{
    while (*root) {
        if (v < (*root)->value) {
            root = &(*root)->left;
        } else if (v > (*root)->value) {
            root = &(*root)->right;
        } else {
            /* duplicate – do nothing */
            return;
        }
    }
    *root = malloc(sizeof(Node));
    if (!*root) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    (*root)->value = v;
    (*root)->left = (*root)->right = NULL;
}

static void print_value(long v, bool *first)
{
    if (!*first) {
        putchar(' ');
    }
    printf("%ld", v);
    *first = false;
}

static void inorder(Node *n, bool *first)
{
    if (!n) return;
    inorder(n->left, first);
    print_value(n->value, first);
    inorder(n->right, first);
}

static void preorder(Node *n, bool *first)
{
    if (!n) return;
    print_value(n->value, first);
    preorder(n->left, first);
    preorder(n->right, first);
}

static void postorder(Node *n, bool *first)
{
    if (!n) return;
    postorder(n->left, first);
    postorder(n->right, first);
    print_value(n->value, first);
}

static void free_tree(Node *n)
{
    if (!n) return;
    free_tree(n->left);
    free_tree(n->right);
    free(n);
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("INVALID_MODE");
        return 0;
    }

    const char *mode = argv[1];
    Node *root = NULL;

    for (int i = 2; i < argc; ++i) {
        long v = strtol(argv[i], NULL, 10);
        insert(&root, v);
    }

    if (root == NULL) {
        puts("EMPTY");
        return 0;
    }

    bool first = true;
    if (strcmp(mode, "in") == 0) {
        inorder(root, &first);
    } else if (strcmp(mode, "pre") == 0) {
        preorder(root, &first);
    } else if (strcmp(mode, "post") == 0) {
        postorder(root, &first);
    } else {
        puts("INVALID_MODE");
        free_tree(root);
        return 0;
    }

    putchar('\n');
    free_tree(root);
    return 0;
}
